#!/usr/bin/env node
/*
 * Builds assets/js/lucide-subset.js — only the Lucide icons this site uses.
 *
 * The full vendored build (assets/vendor/lucide-0.468.0.min.js, ~350 KB) is
 * kept as the source of truth but no page loads it any more. Re-run this
 * script after adding a new `data-lucide="..."` icon anywhere:
 *
 *     node tools/build-lucide-subset.mjs
 *
 * The generated file exposes the same `window.lucide.createIcons()` API and
 * produces the same <svg> markup as the full library.
 */
import { createRequire } from 'node:module';
import { readFileSync, writeFileSync, readdirSync, statSync } from 'node:fs';
import { join, dirname, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const OUT = join(root, 'assets/js/lucide-subset.js');
const SOURCE = join(root, 'assets/vendor/lucide-0.468.0.min.js');
const lucide = createRequire(import.meta.url)(SOURCE);

function walk(dir, files = []) {
    for (const name of readdirSync(dir)) {
        if (name.startsWith('.') || name === 'node_modules' || name === 'vendor') continue;
        const path = join(dir, name);
        if (statSync(path).isDirectory()) walk(path, files);
        else if (/\.(html|js)$/.test(name) && path !== OUT) files.push(path);
    }
    return files;
}

const names = new Set();
for (const file of walk(root)) {
    const text = readFileSync(file, 'utf8');
    for (const match of text.matchAll(/data-lucide=["']([a-z0-9-]+)["']/g)) names.add(match[1]);
}

const toPascal = (name) => name.replace(/(\w)(\w*)(_|-|\s*)/g, (_, first, rest) => first.toUpperCase() + rest.toLowerCase());
const icons = {};
let defaults = null;
for (const name of [...names].sort()) {
    const node = lucide.icons[toPascal(name)];
    if (!node) throw new Error(`Unknown Lucide icon "${name}" (not in lucide 0.468.0)`);
    const [, attrs, children] = node;
    defaults ??= attrs;
    if (JSON.stringify(attrs) !== JSON.stringify(defaults)) throw new Error(`Icon "${name}" has non-default attributes`);
    icons[name] = children;
}

const banner = `/*! Lucide v0.468.0 icon subset (${names.size} icons) | ISC License | https://lucide.dev
 * GENERATED by tools/build-lucide-subset.mjs — do not edit by hand. */`;
const body = `(function () {
    'use strict';
    var NS = 'http://www.w3.org/2000/svg';
    var DEFAULTS = ${JSON.stringify(defaults)};
    var ICONS = ${JSON.stringify(icons)};

    function build(tag, attrs, children) {
        var el = document.createElementNS(NS, tag);
        Object.keys(attrs).forEach(function (key) { el.setAttribute(key, String(attrs[key])); });
        (children || []).forEach(function (child) { el.appendChild(build(child[0], child[1], child[2])); });
        return el;
    }

    function replace(node) {
        var name = node.getAttribute('data-lucide');
        if (!name || node.namespaceURI === NS) return;
        var children = ICONS[name];
        if (!children) {
            console.warn('[lucide-subset] Missing icon "' + name + '". Run node tools/build-lucide-subset.mjs');
            return;
        }
        var own = {};
        Array.prototype.forEach.call(node.attributes, function (attr) { own[attr.name] = attr.value; });
        var attrs = Object.assign({}, DEFAULTS, { 'data-lucide': name }, own);
        var classes = ['lucide', 'lucide-' + name].concat((own['class'] || '').split(/\\s+/));
        attrs['class'] = classes.filter(function (c, i, all) { return c && all.indexOf(c) === i; }).join(' ');
        if (node.parentNode) node.parentNode.replaceChild(build('svg', attrs, children), node);
    }

    function createIcons() {
        Array.prototype.forEach.call(document.querySelectorAll('[data-lucide]'), replace);
    }

    window.lucide = { createIcons: createIcons, icons: ICONS };
    if (window.__lucidePending) {
        window.__lucidePending = false;
        createIcons();
    }
}());
`;
writeFileSync(OUT, `${banner}\n${body}`);
console.log(`Wrote ${relative(root, OUT)}: ${names.size} icons, ${(Buffer.byteLength(banner + body) / 1024).toFixed(1)} KB`);
